"""Brute‑force Clique solver used for testing the reduction.

Instance format follows ``problems.Clique``:
    {"n": n, "edges": [[u, v], ...], "k": k}
The function returns ``True`` iff the graph contains a clique of size at least k.
"""

from __future__ import annotations

from itertools import combinations
from typing import List, Dict, Set, Tuple


def clique_has_at_least_k(instance: Dict[str, object]) -> bool:
    n: int = instance["n"]  # type: ignore[assignment]
    edges: List[List[int]] = instance["edges"]  # type: ignore[assignment]
    k: int = instance["k"]  # type: ignore[assignment]

    # Edge cases per problem statement
    if k <= 0:
        return True
    if n == 0:
        return False
    if k == 1:
        return n >= 1
    if k > n:
        return False

    # Build adjacency set for fast lookup
    adj: List[Set[int]] = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Try all subsets of size k up to n (since we need at least k)
    # We can stop early when a clique is found.
    for size in range(k, n + 1):
        for subset in combinations(range(n), size):
            # Check every pair
            ok = True
            for i, j in combinations(subset, 2):
                if j not in adj[i]:
                    ok = False
                    break
            if ok:
                return True
    return False

EOF"}

